{
  "userQuery": "给我整个能打勾的清单,显示剩余时间数字,点一下跳应用,显示天气,快超时提醒",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.music",
        "abilityName": "com.huawei.hmos.music.MainAbility",
        "uri": "music://home"
      }
    }
  ],
  "dataModel": {
    "value": {
      "antiAddiction": {
        "title": "防沉迷",
        "remainingMinutes": 8,
        "remainingText": "8分钟",
